CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id text UNIQUE NOT NULL DEFAULT ('YD-' || upper(substr(gen_random_uuid()::text,1,8))), name text NOT NULL, phone text UNIQUE NOT NULL, phone_verified boolean NOT NULL DEFAULT false, identity text NOT NULL DEFAULT 'unverified', dob date NOT NULL, role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','support','operator','finance','admin')), restricted boolean NOT NULL DEFAULT false, profile jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY,user_id uuid REFERENCES users NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS otp (phone text PRIMARY KEY, hash text NOT NULL, expires_at timestamptz NOT NULL, attempts int NOT NULL DEFAULT 0, dob date NOT NULL,name text NOT NULL);
CREATE TABLE IF NOT EXISTS identity_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users NOT NULL,provider text NOT NULL,reference text UNIQUE NOT NULL,result text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS shipments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sender_id uuid REFERENCES users NOT NULL,recipient_id uuid REFERENCES users, courier_id uuid REFERENCES users,status text NOT NULL DEFAULT 'draft',custodian_id uuid REFERENCES users, location text NOT NULL DEFAULT 'origin',data jsonb NOT NULL,payment_status text NOT NULL DEFAULT 'unpaid',payout_status text NOT NULL DEFAULT 'pending',dispute_status text NOT NULL DEFAULT 'none',recipient_consent boolean NOT NULL DEFAULT false,invite_hash text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(courier_id IS NULL OR courier_id <> sender_id));
CREATE INDEX IF NOT EXISTS shipments_sender_idx ON shipments(sender_id); CREATE INDEX IF NOT EXISTS shipments_courier_idx ON shipments(courier_id); CREATE INDEX IF NOT EXISTS shipments_status_idx ON shipments(status);
CREATE TABLE IF NOT EXISTS parcels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid REFERENCES shipments NOT NULL,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid REFERENCES shipments NOT NULL,kind text NOT NULL CHECK(kind IN ('person','point','locker')), endpoint text NOT NULL,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS delivery_legs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid REFERENCES shipments NOT NULL,courier_id uuid REFERENCES users,position int NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'pending',UNIQUE(shipment_id,position));
CREATE TABLE IF NOT EXISTS courier_offers (shipment_id uuid REFERENCES shipments,user_id uuid REFERENCES users,created_at timestamptz DEFAULT now(),PRIMARY KEY(shipment_id,user_id));
CREATE TABLE IF NOT EXISTS assignments (shipment_id uuid PRIMARY KEY REFERENCES shipments,courier_id uuid REFERENCES users NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS handover_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid REFERENCES shipments NOT NULL,stage text NOT NULL,issuer_id uuid REFERENCES users NOT NULL,hash text NOT NULL,expires_at timestamptz NOT NULL,attempts int NOT NULL DEFAULT 0,used_at timestamptz);
CREATE TABLE IF NOT EXISTS handovers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid REFERENCES shipments NOT NULL,stage text NOT NULL,from_id uuid REFERENCES users,to_id uuid REFERENCES users,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS tracking_events (id bigserial PRIMARY KEY,shipment_id uuid REFERENCES shipments NOT NULL,actor_id uuid REFERENCES users,status text NOT NULL,detail text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid UNIQUE REFERENCES shipments NOT NULL,provider_ref text UNIQUE NOT NULL,amount int NOT NULL,status text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid UNIQUE REFERENCES shipments NOT NULL,amount int NOT NULL,status text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid UNIQUE REFERENCES shipments NOT NULL,user_id uuid REFERENCES users NOT NULL,amount int NOT NULL,status text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid REFERENCES shipments NOT NULL,author_id uuid REFERENCES users NOT NULL,target_id uuid REFERENCES users NOT NULL,role text NOT NULL CHECK(role IN ('sender','courier','recipient')),stars int NOT NULL CHECK(stars BETWEEN 1 AND 5),comment text NOT NULL,reason text NOT NULL,hidden boolean NOT NULL DEFAULT false,publish_at timestamptz DEFAULT (now()+interval '7 days'),created_at timestamptz DEFAULT now(),UNIQUE(shipment_id,author_id,target_id,role),CHECK(author_id<>target_id));
CREATE TABLE IF NOT EXISTS disputes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid REFERENCES shipments NOT NULL,author_id uuid REFERENCES users NOT NULL,reason text NOT NULL,evidence jsonb DEFAULT '[]',status text NOT NULL DEFAULT 'open',resolution text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (shipment_id uuid PRIMARY KEY REFERENCES shipments);
CREATE TABLE IF NOT EXISTS messages (id bigserial PRIMARY KEY,shipment_id uuid REFERENCES conversations NOT NULL,user_id uuid REFERENCES users NOT NULL,text text NOT NULL,photo_id uuid,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS lockers (id text PRIMARY KEY,name text NOT NULL,city text NOT NULL,kind text NOT NULL CHECK(kind IN ('point','locker')),connected boolean NOT NULL DEFAULT true,fault text,operator_id uuid REFERENCES users);
CREATE TABLE IF NOT EXISTS compartments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),locker_id text REFERENCES lockers NOT NULL,dimensions jsonb NOT NULL,available boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),compartment_id uuid REFERENCES compartments NOT NULL,shipment_id uuid REFERENCES shipments NOT NULL,stage text NOT NULL,status text NOT NULL DEFAULT 'reserved',expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS reservation_active_idx ON reservations(compartment_id) WHERE status IN ('reserved','deposited');
CREATE TABLE IF NOT EXISTS device_events (event_id text PRIMARY KEY,locker_id text REFERENCES lockers NOT NULL,shipment_id uuid REFERENCES shipments,kind text NOT NULL,result text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id bigserial PRIMARY KEY,user_id uuid REFERENCES users NOT NULL,shipment_id uuid REFERENCES shipments,text text NOT NULL,read boolean DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY,actor_id uuid REFERENCES users,action text NOT NULL,entity_id text,detail jsonb DEFAULT '{}',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency (user_id uuid REFERENCES users,key text,action text NOT NULL,response jsonb NOT NULL,PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS files (id uuid PRIMARY KEY,owner_id uuid REFERENCES users NOT NULL,shipment_id uuid REFERENCES shipments,path text NOT NULL,mime text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),author_id uuid REFERENCES users NOT NULL,message_id bigint REFERENCES messages,reason text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS settings (id int PRIMARY KEY DEFAULT 1 CHECK(id=1),data jsonb NOT NULL);
